    if bears == ['black', 'black']:
        return 'black'
    elif bears == ['brown', 'brown']:
        return 'brown'
    elif bears == ['white', 'white']:
        return 'white'
    elif set(bears) == {'black', 'brown'}:
        return 'dark brown'
